def _parse_full_marker(tokenizer: Tokenizer) -> MarkerList:
    retval = _parse_marker(tokenizer)
    # After parsing the marker, allow trailing horizontal whitespace only before END
    while tokenizer.check("WS"):
        # Check if the whitespace contains any newline characters
        if "\n" in tokenizer.next_token.text or "\r" in tokenizer.next_token.text:
            tokenizer.raise_syntax_error("Trailing newline in marker expression")
        tokenizer.read()
    tokenizer.expect("END", expected="end of marker expression")
    return retval

